import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [formData, setFormData] = useState({ day: 'Monday', grade: 'Grade 10', subject: 'Mathematics', time_slot: '', teacher: '' });
  const [searchQuery, setSearchQuery] = useState(''); 

  const fetchClasses = () => axios.get('http://localhost:8081/api/timetable').then(res => setClasses(res.data));
  useEffect(() => { fetchClasses(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (isEditing) {
      axios.put(`http://localhost:8081/api/timetable/${editId}`, formData).then(() => { fetchClasses(); resetForm(); });
    } else {
      axios.post('http://localhost:8081/api/timetable', formData).then(() => { fetchClasses(); resetForm(); });
    }
  };

  const handleDelete = (id) => { if(window.confirm("Delete?")) axios.delete(`http://localhost:8081/api/timetable/${id}`).then(() => fetchClasses()); };

  const handleEdit = (cls) => {
    setIsEditing(true); setEditId(cls.id);
    setFormData({ day: cls.day, grade: cls.grade, subject: cls.subject, time_slot: cls.time_slot, teacher: cls.teacher });
    setShowForm(true);
  };

  const resetForm = () => { setShowForm(false); setIsEditing(false); setEditId(null); setFormData({ day: 'Monday', grade: 'Grade 10', subject: 'Mathematics', time_slot: '', teacher: '' }); };

  const filteredClasses = [...classes].reverse().filter(c => c.subject.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px' }}>
        <h2 style={{ margin: 0 }}>📅 Manage Classes</h2>
        <button onClick={() => { resetForm(); setShowForm(true); }} style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>+ Add Class</button>
      </div>

      <div style={{ backgroundColor: '#fff', borderRadius: '12px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>No.</th>
              <th style={thStyle}>Day</th>
              <th style={thStyle}>Time</th>
              <th style={thStyle}>Grade</th>
              <th style={thStyle}>Subject</th>
              <th style={thStyle}>Teacher</th>
              <th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredClasses.map((c, index) => (
              <tr key={c.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={tdStyle}>{index + 1}</td>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#15803d'}}>{c.day}</td>
                <td style={{...tdStyle, color: '#eab308', fontWeight: 'bold'}}>{c.time_slot}</td>
                <td style={tdStyle}>{c.grade}</td>
                <td style={tdStyle}>{c.subject}</td>
                <td style={tdStyle}>{c.teacher}</td>
                <td style={tdStyle}>
                  <button onClick={() => handleEdit(c)} style={{ border: 'none', background: 'none', cursor: 'pointer' }}>✏️</button>
                  <button onClick={() => handleDelete(c.id)} style={{ border: 'none', background: 'none', cursor: 'pointer' }}>🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '450px' }}>
            <h3>{isEditing ? 'Edit Class' : 'Add Class'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <select value={formData.day} onChange={(e) => setFormData({...formData, day: e.target.value})} style={inputStyle}>
                {['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map(d => <option key={d} value={d}>{d}</option>)}
              </select>
              <input type="text" placeholder="Time (e.g. 3.00 PM - 5.00 PM)" value={formData.time_slot} onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Grade" value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Subject" value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Teacher Name" value={formData.teacher} onChange={(e) => setFormData({...formData, teacher: e.target.value})} required style={inputStyle} />
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px', borderRadius: '8px' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px', backgroundColor: '#15803d', color: 'white', borderRadius: '8px' }}>Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const inputStyle = { padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '12px', fontSize: '13px', textAlign: 'left', color: '#475569' };
const tdStyle = { padding: '12px', fontSize: '13px' };
